contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint64 _number, uint64 _timestamp) public payable {
        // Read state before the attempted update
        uint64 numBefore = c.number();
        uint64 tsBefore = c.timestamp();

        // Attempt to set L1 block values (expected to revert for any caller we can be)
        bool reverted;
        // top-level state-changing call must be top-level; use try/catch to observe revert
        try c.setL1BlockValues(_number, _timestamp, 1, bytes32(0), 1, bytes32(0), 1, 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after the attempted update
        uint64 numAfter = c.number();
        uint64 tsAfter = c.timestamp();
        string memory v = c.version();

        assert(
            keccak256(bytes(v)) == keccak256(bytes("1.0.0"))
            && numAfter == numBefore
            && tsAfter == tsBefore
        );
    }

    receive() external payable {}
}

